function normalizeLengths(){for(const w of state.walls){if(!w.uid)w.uid='wall-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);if(w.line&&scaleForWall23(w)>0)w.planScale=scaleForWall23(w);if(w.line&&!w.planScale){const[a,b]=w.line;w.planScale=pxCm>0?pxCm:Math.hypot(b.x-a.x,b.y-a.y)/Number(w.length);}w.length=floorLength(w.length);}}
