function zoomGeneral(f){generalZoom=Math.min(400,Math.max(50,generalZoom*f));document.querySelectorAll('.globalPlan svg').forEach(s=>s.style.width=generalZoom+'%');}
function planBounds(g){return {width:Math.max(image.width,...g.labels.flatMap(l=>l.box.map(p=>p.x+10))),height:Math.max(image.height,...g.labels.flatMap(l=>l.box.map(p=>p.y+10)))};}
