function markConflicts(results){for(const m of results){for(const row of m.rows)for(const p of row.pieces)delete p.draftConflict;m.warnings??=[];if(m.manual){const error=V7Rules.audit(m.rows);if(error&&!m.warnings.includes(error))m.warnings.push(error);for(const row of m.rows){for(const p of row.pieces){if(p.x<(m.drawFrom??0)-.01||p.x+p.length+p.joint>(m.drawTo??m.L)+.01){p.draftConflict=true;if(!m.warnings.includes('Há bloco fora do comprimento da parede; ajuste manual necessário.'))m.warnings.push('Há bloco fora do comprimento da parede; ajuste manual necessário.');}for(const q of row.pieces)if(q!==p&&Math.min(p.x+p.joint/2+p.length,q.x+q.joint/2+q.length)>Math.max(p.x+p.joint/2,q.x+q.joint/2)+.01){p.draftConflict=q.draftConflict=true;if(!m.warnings.includes('Há blocos sobrepostos nesta fiada.'))m.warnings.push('Há blocos sobrepostos nesta fiada.');}}}}}
 const pages=[...new Set(state.walls.map(w=>Number(w.page||1)))],bad=new Set(),checked=new Set();for(const page of pages)for(let r=0;r<Math.max(0,...results.map(m=>m.rows.length));r++){const key=page+'|'+JSON.stringify(results.map(m=>m.rows[r]?.pieces.map(p=>[p.x,p.length,p.joint])));if(checked.has(key))continue;checked.add(key);const g=PlanEngine.geometry(state.walls,results,page,r),iso=k=>results[k-1]?.isolated116,real=new Set();for(const pr of g.pairs||[]){const ns=String(pr).match(/\d+/g)?.map(Number)||[];if(ns.length===2&&!ns.some(iso))ns.forEach(n=>real.add(n));}for(const p of g.pieces)if(p.conflict&&(iso(p.wall)||real.has(p.wall)||!(g.pairs||[]).length)){bad.add(p.wall-1);results[p.wall-1].rows[r].pieces[p.pieceIndex].draftConflict=true;}}for(const i of bad){results[i].pending=true;if(!results[i].isolated116)results[i].statusReason='Sobreposição de blocos — ajuste manual pendente.';}}
