function sectionX(m){let best=(m.L||1)/2,score=-1;for(const row of m.rows)for(const p of row.pieces){const x=p.x+p.joint/2+p.length/2;const crossed=m.rows.map(r=>r.pieces.find(q=>x>q.x+q.joint/2+.01&&x<q.x+q.joint/2+q.length-.01));const n=crossed.filter(Boolean).length,margin=Math.min(...crossed.filter(Boolean).map(q=>Math.min(x-q.x-q.joint/2,q.x+q.joint/2+q.length-x)));const v=n*1000+margin-Math.abs(x-m.L/2)/100;if(v>score){best=x;score=v;}}return best;}
