function exportSteelCSV(){if(!state.results)return;state.steel=buildSteel();const rows=steelSchedule(),data=[['N','Diametro_mm','Quantidade','Comprimento_unitario_cm','Comprimento_total_m'],...rows.map(r=>[r.n,r.diameter,r.quantity,r.length,r.total.toFixed(2).replace('.',',')]),[],['Bitola','BR. 12 m','Peso_total_kg'],...([...new Set(rows.map(r=>r.diameter))].map(d=>['Ø'+d.toFixed(1).replace('.',','),(rows.filter(r=>r.diameter===d).reduce((sum,r)=>sum+r.total,0)/12).toFixed(2).replace('.',','),(rows.filter(r=>r.diameter===d).reduce((sum,r)=>sum+r.total,0)*steelMassPerMetre(d)).toFixed(2).replace('.',',')]))];download('Relacao_Aco_Modulacao_V25.csv','\ufeff'+data.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');}

function blockQuantityEligible(m,w){return !!m?.rows?.some(r=>r.pieces?.some(p=>!p.fill));}
function blockQuantityDraft(m,w){return !!(m.pending||m.manual||m.errors?.length||m.revisionStale||m.bondIssues?.length||m.meetingPending||m.L&&Math.abs(m.L-Number(w.length))>.01||m.H&&Math.abs(m.H-Number(w.height))>.01);}
