function auditDisplayedBonding(results){for(const m of results){if(!m?.rows?.length)continue;const issues=JunctionEngine.bondAudit(m.rows);m.bondIssues=issues;if(issues.length){m.bondPending=true;m.pending=true;m.statusReason='Amarração pendente — juntas sem defasagem suficiente nas fiadas '+issues.join(', ')+'. Tente outra combinação ou revise os blocos.';m.warnings??=[];const note='Parede não aprovada para o quantitativo final: revisar a amarração entre todas as fiadas.';if(!m.warnings.includes(note))m.warnings.push(note);}}}
function renderResults(joint,results){let html='<h2>Modulação e quantitativos · combinação '+((state.combinationVariant||0)+1)+'</h2><p class="note">Clique novamente em Gerar modulação para solicitar outro arranjo. Quando houver uma única solução disponível, o desenho pode se repetir.</p><div id="globalPlans"></div>',total={};results=ChannelEngine.apply(state.walls,results,state.blocks,{bearing:num($('openingBearing').value),flex:$('flex').checked,fillMax:num($('fillMax').value)});state.results=results;for(let i=0;i<results.length;i++){const w=state.walls[i],m=results[i];if(w.line&&w.planScale){const drawn=Math.hypot(w.line[1].x-w.line[0].x,w.line[1].y-w.line[0].y)/w.planScale;if(Math.abs(drawn-Number(w.length))>2){m.pending=true;m.warnings??=[];const note='Medida cadastrada difere da marcação na escala única: '+fmt(w.length)+' cm / marcação '+fmt(drawn)+' cm. Recalibre ou corrija a marcação.';if(!m.warnings.includes(note))m.warnings.push(note);}}m.quant=drawnBlockQuantity(m);}auditDisplayedBonding(results);const meetingChecks=auditDisplayedMeetings(results);state.steel=buildSteel();state.junctionReports=joint.reports;html+=`<div>${[...joint.reports.filter(r=>!r.ok),...meetingChecks].map(r=>`<p class="${r.ok?'good':'warning'}">${esc(r.message)}</p>`).join('')}</div><p class="note">Escala dos desenhos: 1:${fmt(num($('scale').value))}. Imprima em tamanho real / 100%, sem ajustar à página. A compatibilização é geométrica e precisa da revisão do detalhe do fabricante.</p>`;state.walls.forEach((w,i)=>{const m=results[i];html+=`<article class="wallResult" id="wall-result-${i}"><h3>Parede ${i+1} <span class="pill">${fmt(w.length)} × ${fmt(w.height)} cm · espessura ${fmt(w.width)} cm</span></h3><p class="drawingScale29">Escala 1:${fmt(num($('scale').value))}</p>`;
 if(m.pending||m.manual)html+=`<p class="warning">${esc(m.statusReason||'Modulação parcial — ajuste manual pendente.')} ${esc((m.sourceErrors||[]).join(' '))}</p>`;if(m.errors.length&&!m.rows?.length){html+=m.errors.map(e=>`<p class="error">${esc(e)}</p>`).join('');if(m.suggestions?.length){html+=`<div class="warning"><b>Consultar catálogo / cadastrar novo bloco</b><p>Possíveis dimensões físicas de complemento, calculadas apenas para fechar o comprimento:</p><ul>${m.suggestions.map(s=>`<li>Trecho ${fmt(s.from)}–${fmt(s.to)} cm: <b>${fmt(s.length)} cm de comprimento × ${fmt(s.height)} cm de altura × ${fmt(s.width)} cm de espessura</b>, com junta de ${fmt(s.joint)} cm. Base: ${esc(s.base)} + 1 complemento.</li>`).join('')}</ul><p>Confirme se essa peça cerâmica estrutural existe no fabricante e é adequada ao projeto. A sugestão não garante amarração. Cadastre somente a dimensão real disponível e gere novamente; o programa verificará a combinação. Não há corte ou cadastro automático de uma peça fictícia.</p><button class="secondary noPrint" onclick="registerComplement()">Cadastrar novo bloco</button></div>`;}else if(w.confirmed){html+=`<p class="note">Se faltar uma peça no catálogo, confira com o fabricante e cadastre um novo bloco disponível. A falha também pode decorrer da altura, das aberturas ou da alternância entre fiadas.</p>`;}}else{if(blockQuantityEligible(m,w))Object.entries(m.quant).forEach(([k,v])=>total[k]=(total[k]||0)+v);html+=`<p class="note">Juntas verticais aplicadas nos trechos: ${fmt(m.jointMin)} a ${fmt(m.jointMax)} cm. Comprimento mantido: ${fmt(m.L)} cm.</p><p class="note noPrint">Dois cliques na bolinha antes do N para editar o aço horizontal ou vertical nesta parede.</p><div class="wallViews"><div class="elevationView" style="width:${wallDrawingWidth21(w,m,'elevation')}mm"><h3 class="wallAlignedTitle">Elevação · última fiada em canaleta ${m.topChannel||''}</h3><p class="drawingScale29">Escala 1:${fmt(num($('scale').value))}</p><button class="secondary noPrint" onclick="openLocationEditor24(${i})">Classificação por trecho · U / J</button>${svgWall(w,m,'elevation')}</div><div class="sectionView" style="width:${sectionDrawingWidth21(w)}mm"><h3 class="sectionAlignedTitle">Corte A–A</h3><p class="drawingScale29">Escala 1:${fmt(num($('scale').value))}</p>${svgSection(w,m)}</div><div class="courseViews" style="width:${wallDrawingWidth21(w,m,'first')}mm"><div><h3 class="wallAlignedTitle">Primeira fiada</h3><p class="drawingScale29">Escala 1:${fmt(num($('scale').value))}</p>${svgWall(w,m,'first')}</div><div><h3 class="wallAlignedTitle">Segunda fiada</h3><p class="drawingScale29">Escala 1:${fmt(num($('scale').value))}</p>${m.rows.length>1?svgWall(w,m,'second'):'<p class="note">Parede com somente uma fiada.</p>'}</div></div></div><p>${Object.entries(m.quant).map(([c,q])=>`<span class="pill">${esc(c)}: ${q} peças</span>`).join(' ')}</p>`;const fills=m.rows.flatMap(row=>row.pieces.filter(p=>p.fill&&!p.gap).map(p=>`Fiada ${row.index}: ${fmt(p.length)} cm, posição ${fmt(p.x)} cm`));if(fills.length)html+=`<details open><summary>Fechamentos localizados com graute — conforme detalhe do projetista</summary><p class="note">${fills.join(' · ')}</p></details>`;html+=manualPanel(w,m,i);html+=m.warnings.map(e=>`<p class="warning">${esc(e)}</p>`).join('');}html+='</article>';});
 const failed=results.filter((m,i)=>blockQuantityDraft(m,state.walls[i])||!blockQuantityEligible(m,state.walls[i])).length;const counted=results.map((m,i)=>blockQuantityEligible(m,state.walls[i])?i+1:null).filter(Boolean);html+=`<article class="wallResult"><h3>Quantitativo de blocos ${failed?'— parcial':''}</h3>${failed?`<p class="error">${failed} parede(s) com ajuste manual ou atualização pendente. O total inclui os blocos desenhados nas paredes pendentes. Trechos sem peças não são contabilizados; revisão necessária.</p>`:''}<p class="note">Paredes incluídas: ${counted.length?counted.join(', '):'nenhuma parede com blocos desenhados'}. Encontros pendentes continuam sinalizados no desenho.</p><table><thead><tr><th>Peça</th><th>Quantidade geométrica</th></tr></thead><tbody>${Object.entries(total).map(([c,q])=>`<tr><td>${esc(c)}</td><td>${q}</td></tr>`).join('')}</tbody></table><p class="note">Sem acréscimo de perdas. Inclui peças de encontro aplicadas; inclui canaletas U/J de respaldo, vergas e contravergas; não inclui reforços ou perdas. Confira as juntas alinhadas e os encontros antes de usar em projeto executivo.</p><div class="toolbar noPrint"><button onclick="printPlot26()">Imprimir pranchas / salvar PDF</button><button onclick="exportCSV()">Baixar quantitativos para Excel</button><button onclick="exportDXF()">Exportar fiadas, elevações e resumos em DXF</button></div></article>`;
 html+=channelCutSummary19();html+=steelSummary();$('output').innerHTML=html.replace('<button onclick="exportCSV()">','<button onclick="exportXLSX()">Baixar Excel preenchido</button><button onclick="exportCSV()">');state.results=results;renderGlobalPlans();}

