 const button=$('generate'),payload=generationPayload(),snapshot=JSON.stringify(payload),started=Date.now(),budget=Math.min(180000,Math.max(30000,payload.walls.length*3000));let worker,url,timer,checkpoint,closed=false;
 if(payload.blocks.some(b=>b.active!==false&&!['length','height','width'].every(k=>Number.isFinite(Number(b[k]))&&Number(b[k])>0))){showStatus('Confira as dimensões positivas dos blocos antes de gerar.');return;}
