 url=URL.createObjectURL(new Blob([source],{type:'application/javascript'}));worker=new Worker(url);activeGeneration19={cancel:()=>stop('Cálculo cancelado por você.')};button.disabled=false;button.textContent='Cancelar cálculo';showStatus('Calculando '+payload.walls.length+' paredes em segundo plano…');
