function download(name,text,mime){const url=URL.createObjectURL(new Blob([text],{type:mime}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function svgLinearSubpaths(data){const tokens=String(data).match(/[a-zA-Z]|[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:[eE][-+]?\d+)?/g)||[];let i=0,cmd='',x=0,y=0,sx=0,sy=0,current=null,out=[];const iscmd=t=>/^[a-zA-Z]$/.test(t||'');while(i<tokens.length){if(iscmd(tokens[i]))cmd=tokens[i++];const op=cmd.toUpperCase(),rel=cmd!==op;if(op==='Z'){if(current)current.closed=true;x=sx;y=sy;cmd='';continue;}if(!['M','L','H','V'].includes(op))return null;if(op==='H'){x=(rel?x:0)+Number(tokens[i++]);}else if(op==='V'){y=(rel?y:0)+Number(tokens[i++]);}else{const nx=Number(tokens[i++]),ny=Number(tokens[i++]);if(!Number.isFinite(nx)||!Number.isFinite(ny))return null;x=(rel?x:0)+nx;y=(rel?y:0)+ny;}
if(op==='M'){current={points:[],closed:false};out.push(current);sx=x;sy=y;cmd=rel?'l':'L';}if(!current)return null;current.points.push({x,y});}return out;}

