function openSteelEditor(wall,kind,index){const d=state.steel?.[wall],p=kind==='vertical'?d?.points[index]:d?.horizontals.find(b=>b.editIndex===index);if(!p)return;const key=kind==='vertical'?p.overrideKey:p.key,o=state.steelOverrides?.[key]||{},horizontal=kind==='horizontal';steelEditing19={key,wall,kind,index};const options=v=>[8,10,12.5].map(d=>`<option value="${d}" ${Number(v)===d?'selected':''}>Ø${d.toFixed(1).replace('.',',')} mm</option>`).join('');$('steelEditor').classList.remove('hidden');$('steelEditor').innerHTML=`<h3>Editar aço ${esc(p.n)} · Parede ${wall+1} · ${horizontal?esc(p.kind):'vertical neste ponto'}</h3><p class="note">Esta escolha vale só para este trecho ou ponto. Os demais seguem o padrão geral. No encontro compartilhado, a mesma armadura aparece nas duas paredes e é contada uma vez.</p><div class="row"><label>${horizontal?'Camada superior':'Bitola'}<select id="localSteelDiameter">${options(o.diameter||p.diameter)}</select></label><label>Quantidade de barras<input id="localSteelQuantity" type="number" min="1" max="20" step="1" value="${o.quantity||p.quantity}"></label>${horizontal?`<label>Camada inferior: quantidade (0 = sem camada)<input id="localSteelLowerQuantity" type="number" min="0" max="20" step="1" value="${o.lowerQuantity||0}"></label><label>Bitola da camada inferior<select id="localSteelLowerDiameter">${options(o.lowerDiameter||p.diameter)}</select></label>`:''}</div><button onclick="saveSteelEdit19()">Aplicar neste ponto</button> <button onclick="resetSteelEdit19()">Voltar ao automático</button> <button onclick="closeSteelEditor21()">Fechar</button>`;prepareSteelDialog21(wall,kind,index);if(horizontal){const b=document.createElement('button');b.textContent='Unir com outros aços';b.onclick=()=>startSteelMerge23(wall,index);$('steelEditor').append(b);if(p.merged23){const u=document.createElement('button');u.textContent='Desfazer união';u.onclick=()=>undoSteelMerge23(wall,p);$('steelEditor').append(u);}}$('steelEditor').showModal();}
function saveSteelEdit19(){if(!steelEditing19)return;const quantity=Number($('localSteelQuantity').value),diameter=Number($('localSteelDiameter').value),lowerQuantity=steelEditing19.kind==='horizontal'?Number($('localSteelLowerQuantity').value):0;if(!Number.isInteger(quantity)||quantity<1||quantity>20||!Number.isInteger(lowerQuantity)||lowerQuantity<0||lowerQuantity>20){$('steelEditorError21').textContent='Informe quantidades inteiras entre 1 e 20; a camada inferior também aceita zero.';return;}state.steelOverrides??={};state.steelOverrides[steelEditing19.key]={diameter,quantity,lowerQuantity,lowerDiameter:lowerQuantity?Number($('localSteelLowerDiameter').value):diameter};refreshSteel19();}
function resetSteelEdit19(){if(!steelEditing19)return;delete state.steelOverrides?.[steelEditing19.key];refreshSteel19();}
function refreshSteel19(){const wall=steelEditing19?.wall||0,old=$('wall-result-'+wall),top=old?.getBoundingClientRect().top,sy=window.scrollY,sx=window.scrollX;closeSteelEditor21();renderResults({reports:state.junctionReports||[]},state.results);const restore=()=>{const now=$('wall-result-'+wall);window.scrollTo(sx,Math.max(0,top!=null&&now?window.scrollY+now.getBoundingClientRect().top-top:sy));};restore();requestAnimationFrame(restore);}
function steelEditorAttr19(i,kind,index){return `data-steel-wall="${i}" data-steel-kind="${kind}" data-steel-index="${index}" ondblclick="event.stopPropagation();openSteelEditor(${i},'${kind}',${index})" onclick="event.stopPropagation();toggleSteelMerge23(${i},'${kind}',${index})" style="cursor:pointer"`;}
steelWall=function(w,m,which,from,pad,k){const i=state.walls.indexOf(w),d=state.steel?.[i];if(!d)return '';let out='';if(which==='elevation')for(const [bi,b]of d.horizontals.entries()){const a=pad+(b.start+2.5-from)*k,z=a+b.length*k,yy=pad+(m.H-b.y-b.height*(b.layer==='inferior'?.25:.75))*k,attr=steelEditorAttr19(i,'horizontal',b.editIndex),dy=11.5+bi*6;
 out+=`<g ${attr}><title>Dois cliques: editar ${esc(b.n)}</title><line x1="${a}" y1="${yy}" x2="${z}" y2="${yy}" stroke="#111" stroke-width=".35"/><line x1="${a}" y1="${yy}" x2="${z}" y2="${yy}" data-hit="true" stroke="transparent" stroke-width="3"/><line x1="${a}" y1="${dy}" x2="${z}" y2="${dy}" stroke="#111" stroke-width=".35"/>${steelHandle21(i,'horizontal',b.editIndex,a-1,dy-2.3,b.n)}<text x="${a+1}" y="${dy-1.5}" font-size="2.1">${esc(b.n)} · ${b.quantity} Ø${b.diameter.toFixed(1).replace('.',',')} · C=${fmt(b.length)} cm · ${b.layer}</text></g>`;}
 for(const [pn,p]of d.points.entries()){const x=pad+(p.t-from)*k,y=which==='elevation'?pad+(m.H+10)*k:pad+Number(w.width)*k/2,attr=steelEditorAttr19(i,'vertical',pn);out+=`<g ${attr}><title>Dois cliques: editar ${esc(p.n)} neste ponto</title>`;for(let n=0;n<p.quantity;n++){const dx=(n-(p.quantity-1)/2)*.65;if(which==='elevation')out+=`<line x1="${x+dx}" y1="${pad}" x2="${x+dx}" y2="${y}" stroke="#111" stroke-width=".35"/>`;else out+=`<circle cx="${x+dx}" cy="${y}" r=".2" data-steel-dot37="true" fill="#111"/>`;}out+=which==='elevation'?`<line x1="${x}" y1="${pad}" x2="${x}" y2="${y}" data-hit="true" stroke="transparent" stroke-width="3"/>`:`<circle cx="${x}" cy="${y}" data-hit="true" r="2" fill="transparent"/>`;const ty=which==='elevation'?pad+m.H*k+10:pad-3;out+=(which==='elevation'?steelHandle21(i,'vertical',pn,x-.8,ty-2.3,p.n):'')+steelArrow(x,y,x+1,ty,p.n)+'</g>';}
 return out;};
steelSection=function(w,m,pad,k){const i=state.walls.indexOf(w),d=state.steel?.[i];if(!d)return '';let out='';const cut=sectionX(m);for(const b of d.horizontals){if(cut<b.start+2.5||cut>b.end-2.5)continue;const bx=pad+Number(w.width)*k/2,by=pad+(m.H-b.y-b.height*(b.layer==='inferior'?.25:.75))*k;out+=`<g ${steelEditorAttr19(i,'horizontal',b.editIndex)}>`;for(let n=0;n<b.quantity;n++)out+=`<circle cx="${bx+(n-(b.quantity-1)/2)*.7}" cy="${by}" r=".4" fill="#111"/>`;out+=steelHandle21(i,'horizontal',b.editIndex,pad+Number(w.width)*k+2.2,by-5.3,b.n)+steelArrow(bx,by,pad+Number(w.width)*k+4,by-3,b.n)+'</g>';}
 if(d.quantity){const y2=pad+(m.H+10)*k;for(const [gi,g]of d.verticalGroups.entries()){const x=pad+Number(w.width)*k+4+gi*4.2,pn=d.points.findIndex(p=>p.n===g.n);out+=`<g ${steelEditorAttr19(i,'vertical',pn)}><line data-vertical-detail="${esc(g.n)}" x1="${x}" y1="${pad}" x2="${x}" y2="${y2}" stroke="#111" stroke-width=".35"/><g transform="translate(${x-1.2},${y2-1}) rotate(-90)">${steelHandle21(i,'vertical',pn,-1.8,-.8,g.n)}<text font-size="2.1">${esc(g.n)} · ${g.quantity} Ø${g.diameter.toFixed(1).replace('.',',')} · C=${fmt(g.length)} cm</text></g></g>`;}}return out;};
// Draw the real adjacent-wall courses as context, without changing quantities.
function junctionContext(w,m,which,from,pad,k){const i=state.walls.indexOf(w);if(!w.line)return '';const [wa,wb]=w.line,wl=Math.hypot(wb.x-wa.x,wb.y-wa.y),wk=Number(w.planScale)||wl/Number(w.length),ux=(wb.x-wa.x)/wl,uy=(wb.y-wa.y)/wl;let out='',seen=new Set();const local=(x,y)=>({x:((x-wa.x)*ux+(y-wa.y)*uy)/wk,y:(-(x-wa.x)*uy+(y-wa.y)*ux)/wk});const qs=JunctionEngine.detect(state.walls).filter(q=>q.a.i===i||q.b.i===i);const rows=which==='elevation'?m.rows:[m.rows[which==='first'?0:1]].filter(Boolean);
 for(const q of qs){const own=q.a.i===i,other=own?q.b.i:q.a.i,t=own?q.ta:q.tb,ot=own?q.tb:q.ta,v=state.walls[other],vm=state.results?.[other];if(!v?.line||!vm?.rows?.length)continue;const[va,vb]=v.line,vl=Math.hypot(vb.x-va.x,vb.y-va.y),vk=Number(v.planScale)||vl/Number(v.length),vx=(vb.x-va.x)/vl,vy=(vb.y-va.y)/vl;
 for(const row of rows){const vr=vm.rows.find(r=>r.index===row.index);if(!vr)continue;const ps=vr.pieces.filter(p=>!p.fill);let chosen;if(which==='elevation'){chosen=ps.filter(p=>p.x+p.joint/2+p.length>ot-Number(w.width)/2+.001&&p.x+p.joint/2<ot+Number(w.width)/2-.001);}else{const before=ps.filter(p=>p.x+p.joint/2<ot-Number(w.width)/2-.001).sort((a,b)=>b.x-a.x).slice(0,2),after=ps.filter(p=>p.x+p.joint/2+p.length>ot+Number(w.width)/2+.001).sort((a,b)=>a.x-b.x).slice(0,2);chosen=[...new Set([...before,...after])];}
 for(const p of chosen){const key=[other,row.index,p.x,which].join('|');if(seen.has(key))continue;seen.add(key);const a=p.x+p.joint/2,b=a+p.length,half=Number(v.width)/2,coords=[[a,-half],[b,-half],[b,half],[a,half]].map(([s,z])=>local(va.x+vx*s*vk-vy*z*vk,va.y+vy*s*vk+vx*z*vk));
 if(which!=='elevation'){const points=coords.map(c=>(pad+(c.x-from)*k)+','+(pad+(Number(w.width)/2+c.y)*k)).join(' ');out+=`<polygon data-context-wall="${other+1}" points="${points}" fill="${color(p.code)}" fill-opacity=".7" stroke="#174a78" stroke-width=".18" stroke-dasharray="1 .5"><title>Parede ${other+1} · ${esc(p.code)} · contado na parede de origem</title></polygon>`;}else{let aa=Math.min(...coords.map(c=>c.x)),bb=Math.max(...coords.map(c=>c.x));aa=Math.max(aa,m.drawFrom??0);bb=Math.min(bb,m.drawTo??m.L);let free=[[aa,bb]];for(const ownp of row.pieces.filter(p=>!p.fill)){const x=ownp.x+ownp.joint/2,z=x+ownp.length;free=free.flatMap(([a,b])=>z<=a||x>=b?[[a,b]]:[[a,Math.min(b,x)],[Math.max(a,z),b]].filter(([a,b])=>b-a>.01));}for(const[a,b]of free){if(b-a<Math.min(2,Number(v.width)*.3))continue;const x=pad+(a-from)*k,y=pad+(m.H-p.y-p.height-m.jv/2)*k,bw=(b-a)*k,bh=p.height*k;out+=`<g data-context-wall="${other+1}"><title>Parede ${other+1} · bloco de referência da outra parede</title><rect x="${x}" y="${y}" width="${bw}" height="${bh}" fill="${color(p.code)}" stroke="#174a78" stroke-width=".15"/><path d="M${x},${y}L${x+bw},${y+bh}M${x+bw},${y}L${x},${y+bh}" fill="none" stroke="#111" stroke-width=".25"/></g>`;}}}
 }}return out;}
function channelCutRows19(){const map=new Map();for(const m of state.results||[])for(const row of m.rows||[])for(const p of row.pieces||[]){if(!p.channel||p.fill)continue;const code=p.sourceCode||p.code;let r=map.get(code);if(!r){r={code,whole:0,cuts:[]};map.set(code,r);}if(p.cut)r.cuts.push(p.length);else r.whole++;}return [...map.values()];}
function channelCutSummary19(){const rows=channelCutRows19();if(!rows.length)return '';return `<article class="wallResult"><h3>Canaletas: inteiras e cortes</h3><table><thead><tr><th>Perfil</th><th>Inteiras assentadas</th><th>Peças cortadas</th><th>Comprimentos finais dos cortes (cm)</th><th>Peças de origem</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.code)}</td><td>${r.whole}</td><td>${r.cuts.length}</td><td>${r.cuts.map(fmt).join('; ')||'—'}</td><td>${r.whole+r.cuts.length}</td></tr>`).join('')}</tbody></table><p class="note">Peças de origem: uma canaleta inteira por peça cortada, sem presumir reaproveitamento de sobras. Os cortes fecham o comprimento disponível; não preenchem vãos de aberturas nem espaços reservados ao encontro de outra parede.</p></article>`;}

junctionArrows=function(w,m,which,from,pad,k){const index=state.walls.indexOf(w),qs=JunctionEngine.detect(state.walls).filter(q=>q.a.i===index||q.b.i===index);let out='';for(const [n,q]of qs.entries()){const own=q.a.i===index,other=own?q.b.i:q.a.i,t=own?q.ta:q.tb,xe=pad+(t-from)*k,wall=state.walls[other],model=state.results?.[other],pieces=model?.rows?.[which==='second'?1:0]?.pieces||[],reach=pieces.filter(p=>!p.fill).sort((a,b)=>b.length-a.length).slice(0,2).reduce((s,p)=>s+p.length+p.joint,0);const y=which==='elevation'?pad+m.H*k+14+(n%2)*3:pad+num(w.width)*k+reach*k+7+(n%2)*3,origin=which==='elevation'?pad+m.H*k:pad+num(w.width)*k;out+=`<path d="M${xe},${y-2}V${origin} m-1,1 l1,-1 l1,1" fill="none" stroke="#174a78" stroke-width=".22"/><text x="${xe+3}" y="${y}" font-size="2.2">Parede ${other+1}</text>`;}return out;};

function channelCutDescription19(m,code){const ps=(m.rows||[]).flatMap(r=>r.pieces).filter(p=>p.channel&&p.code===code&&!p.fill);if(!ps.length)return '';const cuts=ps.filter(p=>p.cut);return ' / Canaletas inteiras: '+(ps.length-cuts.length)+'; cortadas: '+cuts.length+'; comprimentos finais: '+(cuts.map(p=>fmt(p.length)).join(', ')||'sem cortes')+' cm; peças de origem: '+ps.length+' (uma por corte, sem reaproveitamento).';}

function wallPad22(w){return 26+Math.max(0,(state.steel?.[state.walls.indexOf(w)]?.horizontals.length||1)-1)*6;}
function sectionDrawingWidth21(w){const k=10/Math.max(1,num($('scale').value)),groups=state.steel?.[state.walls.indexOf(w)]?.verticalGroups.length||1,pad=wallPad22(w);return Math.max(34,num(w.width)*k+pad+12+Math.max(0,groups-1)*4.2)-(pad-10);}
function wallSupport22(x,y,width,k,which){const h=30*k,tx=which==='section'?x+width+1:x+width-2,ty=which==='section'?y+h+5:y+h*.65+1;return `<g data-wall-support="${which}"><rect x="${x}" y="${y}" width="${width}" height="${h}" fill="#eeeeee" stroke="#aaa" stroke-width=".15"/>${which==='section'?`<path d="M${tx},${ty-2}L${x+width*.65},${y+h*.65}" fill="none" stroke="#555" stroke-width=".18"/>`:""}<text x="${tx}" y="${ty}" text-anchor="end" font-size="1.9">Apoio da parede</text></g>`;}
function wallDrawingWidth21(w,m,which){const k=10/Math.max(1,num($('scale').value)),ps=m.rows.flatMap(r=>r.pieces),from=m.manual?Math.min(m.drawFrom??0,...ps.map(p=>p.x)):m.drawFrom??0,to=m.manual?Math.max(m.drawTo??m.L,...ps.map(p=>p.x+p.length+p.joint)):m.drawTo??m.L;return Math.max((to-from)*k+22,which==='elevation'?52:0);}
function steelHandle21(wall,kind,index,x,y,n){return `<g data-editor-handle="true" class="steelEditHandle21" tabindex="0" role="button" aria-label="Editar ${esc(n)}, aço ${kind==='vertical'?'vertical':'horizontal'}, Parede ${wall+1}" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();openSteelEditor(${wall},'${kind}',${index})}"><title>Dois cliques na bolinha: editar ${esc(n)} neste ponto</title><circle cx="${x}" cy="${y}" r="2" fill="transparent"/><circle class="steelEditDot21" cx="${x}" cy="${y}" r=".7" fill="#111"/></g>`;}
function prepareSteelDialog21(wall,kind,index){const editor=$('steelEditor');editor.querySelector('h3').id='steelEditorTitle21';if(kind==='vertical'){const label=document.createElement('label');label.textContent='Ponto vertical nesta parede';const select=document.createElement('select');select.id='localSteelPoint21';select.innerHTML=state.steel[wall].points.map((p,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(p.n)} · posição ${fmt(p.t)} cm desde a origem${p.owner!==wall?' · encontro com Parede '+(p.owner+1):''}</option>`).join('');select.onchange=()=>{const i=Number(select.value);editor.close();openSteelEditor(wall,'vertical',i);};label.append(select);editor.querySelector('.row').prepend(label);}const error=document.createElement('p');error.id='steelEditorError21';error.setAttribute('role','alert');error.style.color='#a22';editor.querySelector('.row').after(error);}
function closeSteelEditor21(){const editor=$('steelEditor');if(editor.open)editor.close();}
$('steelEditor').addEventListener('click',event=>{if(event.target!==$('steelEditor'))return;const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeSteelEditor21();});



function commonCuts23(){const cuts=(state.results||[]).flatMap(m=>(m.rows||[]).flatMap(r=>r.pieces||[])).filter(p=>p.cut&&p.sourceCode==='B39'&&!p.channel).map(p=>p.length);return cuts.length?[{code:'B39',whole:0,cuts}]:[];}

function level23(){const v=Number(String($('baseLevel23').value||0).replace(',','.'));return Number.isFinite(v)?v:0;}
function scaleForWall23(w){const page=Number(w.page)||1;return Number(state.pageScales23?.[page])||((Number($('page').value)||1)===page?pxCm:0)||Number(w.planScale)||0;}
function applyPageScale23(page,scale,remeasure=false){state.pageScales23??={};state.pageScales23[page]=scale;for(const w of state.walls){if(!w.line||Number(w.page||1)!==page)continue;w.planScale=scale;if(remeasure){w.length=Math.floor(Math.hypot(w.line[1].x-w.line[0].x,w.line[1].y-w.line[0].y)/scale);w.confirmed=false;}}invalidate();renderWalls();}
function levelMarks23(pad,bottom,height,k){const top=bottom-height*k,f=v=>(v>=0?'+':'')+v.toFixed(2).replace('.',',')+' m';return [[bottom,level23()],[top,level23()+height/100]].map(([y,v])=>`<path d="M${pad-3},${y} l-2,-2 h4 z M${pad-5},${y} h-9" stroke="#174a78" fill="none" stroke-width=".22"/><text x="${pad-21}" y="${y-2.7}" font-size="2" fill="#174a78">${f(v)}</text>`).join('');}
let mergeSelection23=null;
function barIdentity23(b){return [b.kind,b.start,b.end,b.y,b.length].join('|');}
function applySteelMerges23(data){for(const d of data){const w=state.walls[d.i];for(const merge of state.steelMerges23||[]){if(merge.wall!==w.uid||merge.geometry!==steelGeometryKey(w))continue;const selected=d.horizontals.filter(b=>merge.members.includes(barIdentity23(b)));if(selected.length!==merge.members.length)continue;d.horizontals=d.horizontals.filter(b=>!selected.includes(b));d.horizontals.push({...selected[0],start:merge.start,end:merge.end,length:Math.floor(merge.end-merge.start-5+1e-8),kind:'Aço unido',merged23:merge.id});}d.horizontals.sort((a,b)=>b.y-a.y||a.start-b.start);}}
function startSteelMerge23(wall,index){closeSteelEditor21();mergeSelection23={wall,indices:new Set([index])};let panel=$('mergePanel23');if(!panel){panel=document.createElement('div');panel.id='mergePanel23';panel.className='noPrint';panel.style.cssText='position:sticky;top:0;z-index:50;background:#e6f2ff;border:2px solid #174a78;padding:12px';$('wall-result-'+wall).prepend(panel);}panel.innerHTML='<b>Unir aços horizontais · Parede '+(wall+1)+'</b><p id="mergeStatus23"></p><label>Bitola da barra contínua <select id="mergeDiameter23">'+[8,10,12.5].map(v=>'<option value="'+v+'" '+(v===10?'selected':'')+'>Ø'+v+' mm</option>').join('')+'</select></label><button onclick="confirmSteelMerge23()">Confirmar união</button> <button onclick="cancelSteelMerge23()">Cancelar</button>';updateMergePreview23();panel.scrollIntoView({block:'center'});}
function selectedBars23(){const q=mergeSelection23;if(!q)return [];return [...q.indices].map(index=>state.steel[q.wall].horizontals.find(b=>b.editIndex===index)).filter(Boolean);}
