 if(fit){let tries=0;while(overs.length&&tries++<12){const ratio=Math.max(...overs.map(i=>Math.max(i.w/d.availW,i.h/d.availH)));$('plotScale26').value=Math.ceil(Number($('plotScale26').value)*Math.max(1.1,ratio)*1.05);d=collectPlot26();overs=d.items.filter(i=>i.w>d.availW+.01||i.h>d.availH+.01);}}
 if(overs.length){plotSignature26='';$('plotStatus26').textContent='Não cabe na escala 1:'+Number($('plotScale26').value)+': '+overs.map(i=>i.title).join('; ')+'. Escolha folha maior ou use Ajustar escala para caber.';return false;}
