 selectedPlot33=null;plotSheets26=sheets;plotItems26=d.items;state.plot26=plotSettings26();plotSignature26=plotFingerprint26();previewPlot26();$('plotStatus26').textContent=sheets.length+' folha(s) · '+state.plot26.format+' · escala 1:'+state.plot26.scale+(d.issues.length?' · '+d.issues.length+' aviso(s): '+d.issues.join(' | '):'')+'.';return true;
